def parse_key_value(line: str) -> tuple[str, str]:
    if "=" not in line:
        raise ValueError("Missing '=' separator")

    key, value = line.split("=", 1)
    key = key.strip()
    value = value.strip()

    if key == "":
        raise ValueError("Key cannot be empty")

    return key, value

