import argparse

def validate_limit(value: str) -> int:
    try:
        v = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid int value: {value!r}")
    if not (1 <= v <= 500):
        raise argparse.ArgumentTypeError(
            f"value must be between 1 and 500 inclusive, got {v}"
        )
    return v
