export function isApiError(value: unknown): value is { error: string; code: number } {
  if (value === null || typeof value !== 'object') {
    return false;
  }

  const obj = value as Record<string, unknown>;

  if (typeof obj.error !== 'string') {
    return false;
  }

  if (typeof obj.code !== 'number') {
    return false;
  }

  return true;
}
